package detect

import "github.com/gr0gu/cerberus/internal/model"

// Rule defines the interface for deterministic endpoint threat evaluation.
type Rule interface {
	ID() string
	Evaluate(ev *model.NormalizedEvent, st *HostState, policy *Policy) []Finding
}

// Finding represents an individual detection result generated by evaluating an event.
type Finding struct {
	RuleID         string
	RulesetVersion string
	Title          string
	Severity       string  // "LOW", "MEDIUM", "HIGH", "CRITICAL"
	Score          float64 // 0.0 to 10.0
	MitreTactic    string
	MitreTechnique string
	PIDRoot        uint32
	Evidence       []int64
}
